package com.powerbank.service; import org.springframework.stereotype.Service;import java.util.*;import com.powerbank.entity.*;import com.powerbank.repository.*; @Service public class StationService {private final StationRepository stations;private final PowerBankRepository banks;public StationService(StationRepository s,PowerBankRepository b){stations=s;banks=b;}public List<Station> all(){return stations.findAll();}public Station save(Station s){return stations.save(s);}public List<Map<String,Object>> nearby(double lat,double lon){return stations.findAll().stream().map(s->{Map<String,Object> m=new LinkedHashMap<>();m.put("station",s);m.put("distanceKm",distance(lat,lon,s.latitude,s.longitude));m.put("available",banks.findAll().stream().filter(p->p.station!=null&&p.station.id.equals(s.id)&&"AVAILABLE".equals(p.status)).count());return m;}).sorted(Comparator.comparingDouble(x->(double)x.get("distanceKm"))).toList();}private double distance(double a,double b,double c,double d){double x=Math.toRadians(c-a),y=Math.toRadians(d-b);double h=Math.sin(x/2)*Math.sin(x/2)+Math.cos(Math.toRadians(a))*Math.cos(Math.toRadians(c))*Math.sin(y/2)*Math.sin(y/2);return 6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h));}}
